fn insert(oline: &Vec<char>, l: usize, nl: &Vec<char>, p: usize, at_pos: usize) -> Vec<char> {
    // Validate constraints implied by the problem statement.
    assert!(l <= oline.len(), "l exceeds length of first sequence");
    assert!(p <= nl.len(), "p exceeds length of second sequence");
    assert!(at_pos <= l, "at_pos must be in [0, l]");

    let cap = l.checked_add(p).expect("l + p overflowed usize");
    let mut res: Vec<char> = Vec::with_capacity(cap);

    // 1) First A characters of oline
    res.extend_from_slice(&oline[..at_pos]);

    // 2) First P characters of nl
    res.extend_from_slice(&nl[..p]);

    // 3) Remaining (L - A) characters of oline up to L
    res.extend_from_slice(&oline[at_pos..l]);

    debug_assert_eq!(res.len(), l + p);
    res
}